// @MARKER getRandomDirection (sheet-worker.js:26444)
	function getRandomDirection() {
		direction="";
		switch(getDieRoll(8)) {
			case 1: direction="North"; break;
			case 2: direction="Northeast"; break;
			case 3: direction="East"; break;
			case 4: direction="Southeast"; break;
			case 5: direction="South"; break;
			case 6: direction="Southwest"; break;
			case 7: direction="West"; break;
			case 8: direction="Northwest"; break;
		}
		return direction;
	}

// @MARKER getCriticalFumble (sheet-worker.js:26460)
	function getCriticalFumble(attackType)  {	
		critFumble="";
			if (attackType=="Melee") {
			critRoll=getDieRoll(100);
			if (critRoll<11) { critFumble="Hits solid object[half damage rolled to weapon & object]"; }
			else if (critRoll<21) { critFumble="Hits solid object[full damage rolled to weapon & object]"; }
			else if (critRoll<31) { critFumble="Hits solid object[double damage rolled to weapon & object]"; }
			else if (critRoll<41) { critFumble="Hits another target in range[half damage rolled to random area on target]"; }
			else if (critRoll<51) { critFumble="Hits another target in range[full damage rolled to random area on target]"; }
			else if (critRoll<61) { critFumble="Hits another target in range[double damage rolled to random area on target]"; }
			else if (critRoll<71) { critFumble="Hits self[half damage rolled to random area]"; }
			else if (critRoll<81) { critFumble="Hits self[full damage rolled to random area]"; }
			else if (critRoll<91) { critFumble="Hits self[double damage rolled to random area]"; }
			else if (critRoll<95) { critFumble="Trip on weapon[fall to the ground losing "+(getDieRoll(6)+1)+" seconds to stand]"; }
			else if (critRoll<99) { critFumble="Trip on weapon, damaging self[full damage rolled to random area, fall to the ground losing "+(getDieRoll(6)+1)+" seconds to stand]"; }
			else if (critRoll<100) {
				if ((getDieRoll(100))<20) {
					critFumble="Trip on weapon, damaging self, losing weapon[full damage rolled to random area, fall to the ground losing "+(getDieRoll(6)+1)+" seconds to stand, weapon thrown " +(getDieRoll(20)) + " feet " +getRandomDirection()+ "]";
				} else {
					critFumble="Trip on weapon, damaging self, losing weapon[full damage rolled to random area bypassing armor, fall to the ground losing "+(getDieRoll(6)+1)+" seconds to stand, weapon thrown " +(getDieRoll(20))+ " feet " +getRandomDirection()+ "]";
				}
			} else if (critRoll==100) {
				if ((getDieRoll(100))<20) {
					critFumble="Trip on weapon, damaging self, losing weapon[double damage rolled to random area, fall to the ground stunned for " +(getDieRoll(3))+ " seconds then losing "+(getDieRoll(6)+1)+" seconds to stand, weapon thrown " +(getDieRoll(20)) + "feet "+getRandomDirection()+"]";
				} else {
					critFumble="Trip on weapon, damaging self, losing weapon[double damage rolled to random area bypassing armor, fall to the ground stunned for " +(getDieRoll(3))+ " seconds then losing "+(getDieRoll(6)+1)+" seconds to stand, weapon thrown " +(getDieRoll(20)) + "feet " +getRandomDirection() +"]";
				}
			}
		} else { // Missile
			critFumble="Missile weapon breaks (and is unusable until repaired)";
		}
		return critFumble;
	}

// @MARKER getFractionalWeight (sheet-worker.js:26494)
