// @MARKER getMaximumTimeDistance (sheet-worker.js:27899)
	function getMaximumTimeDistance(tempAura) {
		tempMaxTimeDistance="";
		tempExtraTime=0;
		tempAura=parseInt(tempAura)||0;
		if (tempAura<2) {
			tempMaxTimeDistance="No time distance (minimum of 2 Aura)";
		} else if (tempAura<4) {
			tempMaxTimeDistance="up to 1 hour distance";
		} else if (tempAura<6) {
			tempMaxTimeDistance="up to 6 hours distance";
		} else if (tempAura<8) {
			tempMaxTimeDistance="up to 12 hours distance";
		} else if (tempAura<10) {
			tempMaxTimeDistance="up to 1 day distance";
		} else if (tempAura<12) {
			tempMaxTimeDistance="up to 5 days distance";
		} else if (tempAura<14) {
			tempMaxTimeDistance="up to 1 week distance";
		} else if (tempAura<16) {
			tempMaxTimeDistance="up to 2 weeks distance";
		} else if (tempAura<18) {
			tempMaxTimeDistance="up to 1 month distance";
		} else if (tempAura<20) {
			tempMaxTimeDistance="up to 6 months distance";
		} else if (tempAura<21) {
			tempMaxTimeDistance="up to 1 year distance";
		} else if (tempAura<41) {
			tempExtraTime=parseInt(tempAura-20);
			tempExtraTime=parseInt(tempExtraTime+1);
			tempMaxTimeDistance="up to "+tempExtraTime+" years distance";
		} else if (tempAura<61) {
			tempExtraTime=parseInt(tempAura-40);
			tempExtraTime=parseInt(tempExtraTime*10);
			tempExtraTime=parseInt(tempExtraTime+21);
			tempMaxTimeDistance="up to "+tempExtraTime+" years distance";
		} else if (tempAura<81) {
			tempExtraTime=parseInt(tempAura-60);
			tempExtraTime=parseInt(tempExtraTime*100);
			tempExtraTime=parseInt(tempExtraTime+221);
			tempMaxTimeDistance="up to "+tempExtraTime+" years distance";
		} else {
			tempExtraTime=parseInt(tempAura-80);
			tempExtraTime=parseInt(tempExtraTime*1000);
			tempExtraTime=parseInt(tempExtraTime+2221);
			tempMaxTimeDistance="up to "+tempExtraTime+" years distance";		
		}		
		return tempMaxTimeDistance;	
	}

