// @MARKER getShrinkSize (sheet-worker.js:29133)
	function getShrinkSize(tempSpellAura) {
		tempSizeString="";
		tempDuration=tempSpellAura*10;
		if (tempSpellAura<3) { tempSizeString = "shrinks to 90% of normal size for "+tempDuration+" min.";	}
		else if (tempSpellAura<5) { tempSizeString = "shrinks to 80% of normal size for "+tempDuration+" min."; }
		else if (tempSpellAura<7) { tempSizeString = "shrinks to 70% of normal size, and loses 1 STR for "+tempDuration+" min."; }
		else if (tempSpellAura<9) { tempSizeString = "shrinks to 60% of normal size, and loses 1 STR for "+tempDuration+" min."; }
		else if (tempSpellAura<11) { tempSizeString = "shrinks to 50% of normal size, and loses 2 STR for "+tempDuration+" min."; }
		else if (tempSpellAura<13) { tempSizeString = "shrinks to 40% of normal size, and loses 2 STR for "+tempDuration+" min."; }
		else if (tempSpellAura<15) { tempSizeString = "shrinks to 30% of normal size, and loses 3 STR for "+tempDuration+" min."; }
		else if (tempSpellAura<17) { tempSizeString = "shrinks to 20% of normal size, and loses 3 STR for "+tempDuration+" min."; }
		else if (tempSpellAura<19) { tempSizeString = "shrinks to 10% of normal size, and loses 4 STR for "+tempDuration+" min."; }
		else { tempSizeString = "shrinks to 1% of normal size, and is reduced to 5 STR for "+tempDuration+" min."; }
		return tempSizeString;
	}

// @MARKER getGrowSize (sheet-worker.js:29149)
	function getGrowSize(tempSpellAura) {
		tempSizeString="";
		tempDuration=tempSpellAura*10;
		if (tempSpellAura<3) { tempSizeString = "grows to 110% of normal size for "+tempDuration+" min.";	}
		else if (tempSpellAura<5) { tempSizeString = "grows to 120% of normal size for "+tempDuration+" min."; }
		else if (tempSpellAura<7) { tempSizeString = "grows to 130% of normal size, and gains 1 STR for "+tempDuration+" min."; }
		else if (tempSpellAura<9) { tempSizeString = "grows to 140% of normal size, and gains 1 STR for "+tempDuration+" min."; }
		else if (tempSpellAura<11) { tempSizeString = "grows to 150% of normal size, and gains 2 STR for "+tempDuration+" min."; }
		else if (tempSpellAura<13) { tempSizeString = "grows to 160% of normal size, and gains 2 STR for "+tempDuration+" min."; }
		else if (tempSpellAura<15) { tempSizeString = "grows to 170% of normal size, and gains 3 STR for "+tempDuration+" min."; }
		else if (tempSpellAura<17) { tempSizeString = "grows to 180% of normal size, and gains 3 STR for "+tempDuration+" min."; }
		else if (tempSpellAura<19) { tempSizeString = "grows to 190% of normal size, and gains 4 STR for "+tempDuration+" min."; }
		else { tempSizeString = "grows to 200% of normal size, and gains 5 STR for "+tempDuration+" min."; }	
		tempSizeString=tempSizeString+" Armor bursts: Leather (1d6), Scale/Ring (2d6), Chain (3d6), Plate (4d6) to each area protected.";
		return tempSizeString;
	}

