// @MARKER getNextAttackSkill (sheet-worker.js:29259)
	function getNextAttackSkill(attackSkill) {
		tmpNewAttackSkill="";
		switch (attackSkill) {
			case "Beginner":
				tmpNewAttackSkill="Novice";
				break;
			case "Novice":
				tmpNewAttackSkill="Intermediate";
				break;
			case "Intermediate":
				tmpNewAttackSkill="Advanced";
				break;
			case "Advanced":
				tmpNewAttackSkill="Expert";
				break;
			case "Expert":
				tmpNewAttackSkill="Master";
				break;
			case "Master":
				tmpNewAttackSkill="Grandmaster";
				break;
			case "Grandmaster":
				tmpNewAttackSkill="Grandmaster";
				break;
		}
		return tmpNewAttackSkill;
	}

