// @MARKER getChaosTouchEffect (sheet-worker.js:171284)
	function getChaosTouchEffect(tempSpellAura) {
		tempChaosTouchEffect="";
		tempd4Roll=rollDiceFromString("1d4");
		tempDurationValue=parseInt(tempd4Roll*10);
		tempPercentileRoll=rollDiceFromString("1d100");
		if (tempPercentileRoll==1) {
			tempChaosValue1=divideWithMin(tempSpellAura, 4);
			tempDiceString=""+tempChaosValue1+"d4";
			tempChaosValue2=rollDiceFromString(tempDiceString);
			tempChaosTouchEffect="HEALED: touched being is healed "+tempDiceString+"="+tempChaosValue2+" damage to all areas instantly";
		} else if (tempPercentileRoll<11) {
			tempChaosTouchEffect="PARALYSIS: touched being makes a MR or is paralyized for "+tempDurationValue+" sec";
		} else if (tempPercentileRoll<21) {
			tempChaosTouchEffect="REVEAL AURA: touched being makes a MR or their Aura glows in the color of their Alignment making them easier to hit for "+tempDurationValue+" min";
		} else if (tempPercentileRoll<31) {
			tempChaosValue1=parseInt(tempSpellAura*4);
			tempChaosValue1=tempChaosValue1+1;
			tempChaosTouchEffect="SLUMBER: touched being makes a MR or sleeps (if under 15 WIL, and under "+tempChaosValue1+" END) for "+tempDurationValue+" min";
		} else if (tempPercentileRoll<41) {
			tempFlipCoin=rollDiceFromString("1d2");
			tempRandomAura=rollDiceFromString("1d20");
			tempChaosValue1=""+getGrowSize(tempRandomAura);
			tempChaosValue2=""+getShrinkSize(tempRandomAura);
			tempChaosValue3=rollDiceFromString("1d6");
			tempChaosValue4=rollDiceFromString("2d6");
			tempChaosValue5=rollDiceFromString("3d6");
			tempChaosValue6=rollDiceFromString("4d6");
			if (tempFlipCoin==1) { // Grow
				tempSpellAction="SIZE CHANGE: touched being grows: "+tempChaosValue1+" for "+tempDurationValue+" min. Possessions and objects on the caster do not change size. Armor burst damage is as follows: LEATHER: 1d6="+tempChaosValue3+", SCALE/RING: 2d6="+tempChaosValue4+", CHAIN: 3d6="+tempChaosValue5+", or PLATE: 4d6="+tempChaosValue6+" to all areas protected";
			} else { // Shrink
				tempSpellAction="SIZE CHANGE: touched being shrinks: "+tempChaosValue2+" for "+tempDurationValue+" min. Possessions and objects on the caster do not change size";
			}
		} else if (tempPercentileRoll<51) {
			tempChaosTouchEffect="CHANGE GENDER: touched being changes to the opposite gender for 1 day";
		} else if (tempPercentileRoll<60) {
			tempFlipCoin=rollDiceFromString("1d2");
			tempChaosDuration1=parseInt(tempSpellAura);
			tempChaosValue1=rollDiceFromString("1d4+1");
			if (tempFlipCoin==1) { // Grow hair
				tempChaosTouchEffect="GROW HAIR: touched being becomes covered in a thick animalistic hair. The target is allowed a MR and if that fails they become covered in fur. If they are already an animal (or furry) the hair doubles in length and thickness. This reduces APP in humanoids by 1d4+1="+tempChaosValue1+" points. If the MR roll succeeds the skin merely itches for a "+tempChaosDuration1+" min. Extra hair falls out after "+tempChaosDuration1+" day(s), leaving behind the unharmed, normal hair. Extra hair can make the wearing of armor difficult causing pulling and catching and reduces initiative by 1 until the extra hair is gone. 1d4+1="+tempChaosValue1+" points of hide are added for the duration of the furry state. Creatures identified as Magical, Magical Animal, Slime, Magical Humanoid, or Undead are unaffected by this spell";
			} else { // Lose hair
				tempChaosTouchEffect="LOSE HAIR: touched being loses all air, including eyelashes. The target is allowed a MR and if that fails all their hair, including eyelashes, immediately fall out. This reduces APP in humanoids by 1d4+1="+tempChaosValue1+" points. If the MR roll succeeds the hair follicles are only mildly itchy for a "+tempChaosDuration1+" min. Lack of hair in animals and beings normally furred causes them to be colder and can cause clothes and armor to chafe, creating rashes and discomfort. Initiative is reduced by 1 for 2 weeks as the hair regrows. Hair grows back at a normal rate. Any furred being with hide has the hide reduced by half for two weeks. Creatures identified as Magical, Magical Animal, Slime, Magical Humanoid, or Undead are unaffected by this spell";
			}
		} else if (tempPercentileRoll==60) {
			tempChaosTouchEffect="MAGICAL PROTECTION: touched being is protected against all negative magical effects at a 99% chance for each effect (modifiers still apply) for "+tempd4Roll+" hour(s)";
		} else if (tempPercentileRoll==61) {
			tempChaosTouchEffect="DIVINE MAGICAL PROTECTION: touched being is protected against all negative divine magical effects at a 99% chance for each effect (modifiers still apply) for "+tempd4Roll+" hour(s)";
		} else if (tempPercentileRoll<71) {
			tempChaosTouchEffect="ITEM DISAPPEARS: touched being loses 1 non-magical, generic item. It seemingly vanishes";
		} else if (tempPercentileRoll<81) {
			tempChaosValue1=getRandomAnimal();
			tempChaosTouchEffect="CHANGE OTHER: touched being changes into a "+tempChaosValue1+" for "+tempDurationValue+" hours";
		} else if (tempPercentileRoll<86) {
			tempChaosTouchEffect="WEAPON DISAPPEARS: touched being loses 1 non-magical weapon. It seemingly vanishes";
		} else if (tempPercentileRoll<91) {
			tempChaosTouchEffect="ARMOR DISAPPEARS: touched being loses 1 non-magical armor piece. It seemingly vanishes";
		} else if (tempPercentileRoll<94) {
			tempPercentileRoll2=rollDiceFromString("1d100");
			if (tempPercentileRoll2<26) {
				tempChaosTouchEffect="TRANSMUTED TO WOOD: touched being makes a MR or is transmuted to wood for "+tempDurationValue+" min";
			} else if (tempPercentileRoll2<51) {
				tempChaosTouchEffect="TRANSMUTED TO STONE: touched being makes a MR or is transmuted to stone for "+tempDurationValue+" min";
			} else if (tempPercentileRoll2<76) {
				tempChaosTouchEffect="TRANSMUTED TO METAL: touched being makes a MR or is transmuted to metal for "+tempDurationValue+" min";
			} else if (tempPercentileRoll2<100) {
				tempChaosTouchEffect="TRANSMUTED TO CRYSTAL: touched being makes a MR or is transmuted to crystal for "+tempDurationValue+" min";
			} else { // 100
				tempChaosTouchEffect="TRANSMUTED TO FLESH: touched being makes a MR or is transmuted to flesh for "+tempDurationValue+" min";
			}
		} else if (tempPercentileRoll<97) {
			tempChaosValue1=rollDiceFromString("1d100");
			tempChaosValue2=getRandomDirection();			
			tempChaosTouchEffect="TELEPORTED AWAY: touched being makes a MR or is teleported "+tempChaosValue1+" mile(s) "+tempChaosValue2;
		} else if (tempPercentileRoll<99) {
			tempChaosValue1=getRandomPlane();			
			tempChaosTouchEffect="BANISHED: touched being makes a MR or is banished to "+tempChaosValue1;
		} else if (tempPercentileRoll<100) {
			tempDiceString=""+tempSpellAura+"d4";
			tempChaosValue1=rollDiceFromString(tempDiceString);
			tempChaosValue2=divideWithMin(tempSpellAura, 4);
			tempChaosTouchEffect="WITHERED: The touched being takes "+tempDiceString+"="+tempChaosValue1+" death damage in the area touched if a MR fails. Even if the Resistance is made, the affected being takes "+tempSpellAura+" point(s) of damage from the withering of skin and muscle in the area affected. APP is reduced by "+tempChaosValue2+" point(s) in any visibly damaged area. Tissues damaged by this spell take twice the normal time to heal and require twice as much magical healing. A being cannot be lowered below 5 APP by this spell`s effects";
		} else { // 100
			tempChaosTouchEffect="WITHERED: The touched being makes a MR or is disentegrated.";		
		}		
		return tempChaosTouchEffect;	
	}

